insert into public.missions (id, category, teaser, title, body, locale, is_active)
values
  ('a1f2e3d4-c5b6-4789-a012-345678050001'::uuid, 'creativity'::public.mission_category, 'A receipt, envelope, or scrap is enough.', 'Mission: tiny collage', 'Find three small scraps of paper from around you. Arrange them into a picture, pattern, or scene on a table. Change it once, then leave it. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050002'::uuid, 'creativity'::public.mission_category, 'Give an ordinary object a secret history.', 'Mission: object backstory', 'Choose one object within reach. Invent a three-sentence story about where it came from before it reached you. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050003'::uuid, 'creativity'::public.mission_category, 'Your voice can make something no one else can.', 'Mission: hum a soundtrack', 'Look out a window or around the room. Hum a short soundtrack for what you see, even if it sounds strange. Let it last one minute. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050004'::uuid, 'creativity'::public.mission_category, 'Turn five words into something unexpected.', 'Mission: five-word poem', 'Pick five random words from signs, packaging, or memory. Arrange them into the shortest poem you can. Read it once and stop.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050005'::uuid, 'creativity'::public.mission_category, 'Draw without looking down.', 'Mission: blind sketch', 'Choose a nearby object. Draw its outline without looking at the page while your hand moves. When you''re done, put the pen down. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050006'::uuid, 'creativity'::public.mission_category, 'One sound is waiting to become music.', 'Mission: kitchen rhythm', 'Tap two household items gently and listen to the different tones. Create a simple rhythm that lasts ten seconds. Repeat it once, then stop.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050007'::uuid, 'creativity'::public.mission_category, 'A shadow can become a picture.', 'Mission: trace a shape', 'Find an interesting shadow or outline nearby. Trace it on paper or in the air with your finger. Add one detail and finish there.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050008'::uuid, 'creativity'::public.mission_category, 'Borrow a color from the world around you.', 'Mission: color hunt', 'Notice one color that appears at least three times around you. Make a quick list or sketch inspired by it. Stop after the third example.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050009'::uuid, 'creativity'::public.mission_category, 'Tell a story in exactly three lines.', 'Mission: three-line tale', 'Write a beginning, middle, and end using only one line each. Keep it simple. When the third line is done, you''re finished.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050010'::uuid, 'creativity'::public.mission_category, 'Rearrange something for beauty, not function.', 'Mission: tabletop composition', 'Gather three nearby objects. Arrange them into a display that pleases you for any reason at all. Look at it for a moment, then move on.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050011'::uuid, 'creativity'::public.mission_category, 'Name something that doesn''t need a name.', 'Mission: invent a name', 'Choose a tree, rock, cloud, chair, or other ordinary thing. Give it a name that feels right. Use the name in one sentence. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050012'::uuid, 'creativity'::public.mission_category, 'Make a postcard no one will send.', 'Mission: imaginary postcard', 'Imagine you''re somewhere else for a day. Write two sentences for a postcard from that place. Stop after signing it with any name you like.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050013'::uuid, 'creativity'::public.mission_category, 'A leaf, stone, or twig can be a tool.', 'Mission: natural pattern', 'If you''re outdoors, collect one small natural object from the ground. Use it to create a temporary pattern or arrangement. Leave it there and continue your day.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050014'::uuid, 'creativity'::public.mission_category, 'Describe a sound without naming it.', 'Mission: sound portrait', 'Listen for a nearby sound. Describe it using shapes, textures, or weather instead of its actual source. Stop after three descriptions.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050015'::uuid, 'creativity'::public.mission_category, 'Make a map that won''t help anyone navigate.', 'Mission: memory map', 'Sketch a rough map of a room, garden, street, or place you know well. Include one detail from memory that matters only to you. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050016'::uuid, 'creativity'::public.mission_category, 'Turn today''s weather into a character.', 'Mission: weather character', 'Imagine the current weather as a person. Give them one habit and one goal. Leave the story there.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050017'::uuid, 'creativity'::public.mission_category, 'One minute. One continuous line.', 'Mission: single-line drawing', 'Put pen to paper and draw without lifting it. Let the line wander into anything it becomes. Stop after one minute.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050018'::uuid, 'creativity'::public.mission_category, 'Make up a tiny celebration.', 'Mission: invent a holiday', 'Create a holiday for something ordinary, like rain on a roof or finding a lost button. Decide how people celebrate it in one sentence. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050019'::uuid, 'creativity'::public.mission_category, 'The next object you notice has a role to play.', 'Mission: cast the object', 'Notice the first object that catches your attention. Imagine it as a character in a film or novel. Give it one line of dialogue and stop.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050020'::uuid, 'creativity'::public.mission_category, 'Build something that lasts five minutes.', 'Mission: temporary sculpture', 'Use coins, stones, blocks, paper, or similar items nearby. Create a small sculpture. Leave it up briefly, then let it go.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050021'::uuid, 'creativity'::public.mission_category, 'Collect details, not things.', 'Mission: texture inventory', 'Find four different textures around you. Describe each in a few words on paper or out loud. Stop after the fourth.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050022'::uuid, 'creativity'::public.mission_category, 'A conversation starter for yourself.', 'Mission: curious question', 'Write a question you don''t know the answer to and aren''t trying to solve today. Add one possible answer just for fun. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050023'::uuid, 'creativity'::public.mission_category, 'Create a title before the artwork exists.', 'Mission: title first', 'Invent a title for a painting, song, or book that doesn''t exist. Then spend two minutes imagining it. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050024'::uuid, 'creativity'::public.mission_category, 'Change one familiar phrase.', 'Mission: remix a saying', 'Think of a common saying or expression. Replace one word and see what happens. Keep the version you like best and move on.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050025'::uuid, 'creativity'::public.mission_category, 'Look up. There''s material there.', 'Mission: cloud or ceiling story', 'Study a cloud, ceiling pattern, or patch of light. Imagine a scene hidden inside it. Describe the scene in two sentences. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050026'::uuid, 'creativity'::public.mission_category, 'Make something together in under two minutes.', 'Mission: shared invention', 'If someone is nearby, take turns adding one sentence to an imaginary story. Stop after six sentences total. If you''re alone, play both roles.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050027'::uuid, 'creativity'::public.mission_category, 'Design a symbol for today.', 'Mission: personal emblem', 'Draw a simple symbol that captures how today feels so far. It can be abstract or literal. When it feels complete, stop.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050028'::uuid, 'creativity'::public.mission_category, 'One object. Three uses it never had.', 'Mission: alternate purposes', 'Choose a nearby object. Invent three completely different uses for it, no matter how impractical. Stop after the third idea.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050029'::uuid, 'creativity'::public.mission_category, 'Write a note from a future afternoon.', 'Mission: future message', 'Imagine yourself one month from now. Write a short note back to today. Keep it to three sentences or fewer. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050030'::uuid, 'creativity'::public.mission_category, 'Find beauty in repetition.', 'Mission: repeating pattern', 'Notice a repeating pattern nearby: bricks, fence posts, tiles, branches, or something else. Sketch or describe it in your own style. Stop after a few minutes.', 'en', true)
